import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// Layouts
import AuthLayout from '../layouts/AuthLayout';
import DashboardLayout from '../layouts/DashboardLayout';

// Garde
import PrivateRoute from './PrivateRoute';

// Pages publiques
import LoginPage    from '../pages/LoginPage';
import RegisterPage from '../pages/RegisterPage';

// Pages privées (à créer progressivement)
import DashboardPage    from '../pages/DashboardPage';
import UnauthorizedPage from '../pages/UnauthorizedPage';

/**
 * Redirige intelligemment selon le rôle après login
 */
const RoleRedirect = () => {
  const { user } = useAuth();
  if (user?.role === 'admin')        return <Navigate to="/admin/dashboard" replace />;
  if (user?.role === 'receptionist') return <Navigate to="/reception/dashboard" replace />;
  return <Navigate to="/client/dashboard" replace />;
};

const AppRouter = () => (
  <BrowserRouter>
    <Routes>

      {/* ── Routes publiques (layout centré / épuré) ── */}
      <Route element={<AuthLayout />}>
        <Route path="/login"    element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
      </Route>

      {/* ── Routes privées communes ── */}
      <Route element={<PrivateRoute />}>
        <Route element={<DashboardLayout />}>
          <Route path="/dashboard" element={<RoleRedirect />} />
          <Route path="/unauthorized" element={<UnauthorizedPage />} />

          {/* Admin uniquement */}
          <Route element={<PrivateRoute allowedRoles={['admin']} />}>
            <Route path="/admin/dashboard" element={<DashboardPage />} />
            {/* À compléter : /admin/rooms, /admin/users… */}
          </Route>

          {/* Réceptionniste + Admin */}
          <Route element={<PrivateRoute allowedRoles={['admin', 'receptionist']} />}>
            <Route path="/reception/dashboard" element={<DashboardPage />} />
            {/* À compléter : /reception/reservations… */}
          </Route>

          {/* Client connecté */}
          <Route element={<PrivateRoute allowedRoles={['client', 'admin', 'receptionist']} />}>
            <Route path="/client/dashboard" element={<DashboardPage />} />
            {/* À compléter : /client/reservations, /client/profile… */}
          </Route>
        </Route>
      </Route>

      {/* ── Fallback ── */}
      <Route path="/" element={<Navigate to="/login" replace />} />
      <Route path="*" element={<Navigate to="/login" replace />} />

    </Routes>
  </BrowserRouter>
);

export default AppRouter;
